CREATE TABLE p(id INTEGER PRIMARY KEY, k INT, v INT, s TEXT);
CREATE TABLE q(id INTEGER PRIMARY KEY, k INT, v INT, s TEXT COLLATE NOCASE);
CREATE TABLE n(k INT, v INT, s TEXT);
CREATE TABLE e(k INT, v INT, s TEXT);
CREATE TABLE f(k INT, v INT, s TEXT);
INSERT INTO p VALUES (1, 1, 2, '1'), (2, 2, 3, 'b'), (3, NULL, 1, 'B'), (4, 4, NULL, NULL), (5, 1, 0, '2');
INSERT INTO q VALUES (1, 2, 2, 'B'), (2, 2, 0, 'a'), (3, 5, 1, '1'), (4, NULL, 4, NULL), (5, 1, 1, 'c');
INSERT INTO n VALUES (1, 2, '2'), (NULL, 1, 'b'), (2, 2, NULL), (3, 0, 'A'), (1, NULL, '1');
INSERT INTO f VALUES (1, 2, '2'), (2, 1, 'b'), (2, 5, NULL);
SELECT a0.k, a1.k, a2.k FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k LEFT JOIN e AS a2 ON a1.k = a2.v WHERE (SELECT min(s1.k) FROM p AS s1 WHERE a0.k < NULL) IS NOT (a2.k - a2.k);
SELECT a0.k, a1.k, a2.k FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k LEFT JOIN e AS a2 ON a1.k = a2.v WHERE (SELECT max(n.v) FROM n WHERE n.k = a0.k) = a2.k;
SELECT a0.k, a1.k, a2.k FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k LEFT JOIN e AS a2 ON a1.k = a2.v WHERE (SELECT a0.k) = a2.k;
SELECT a0.k, a1.k, a2.k FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k LEFT JOIN f AS a2 ON a1.k = a2.v WHERE (SELECT a0.k) = a2.k;
SELECT a0.k, a1.k, a2.k FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k LEFT JOIN f AS a2 ON a1.k = a2.v WHERE (SELECT a0.k) IS NOT a2.k;
SELECT a0.k, a1.k, a2.k FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k JOIN f AS a2 ON a1.k = a2.v WHERE (SELECT a0.k) IS NOT a2.v;
SELECT a0.k, a1.k, a2.k FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k JOIN f AS a2 ON a1.k = a2.v WHERE (SELECT count(*) FROM n WHERE n.k = a0.k) = a2.v;
SELECT a0.k, a1.k, a2.k FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k LEFT JOIN f AS a2 ON a1.k = a2.v WHERE (SELECT count(*) FROM n WHERE n.k = a0.k) + a2.k IS NULL;
SELECT a0.k, a1.k, a2.k, (SELECT count(*) FROM n WHERE n.k = a0.k) FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k LEFT JOIN f AS a2 ON a1.k = a2.v;
SELECT a0.k, a1.k, a2.k, (SELECT count(*) FROM n WHERE n.k = a0.k) FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k JOIN f AS a2 ON a1.k = a2.v;
SELECT count(*), sum(a2.k) FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k LEFT JOIN f AS a2 ON a1.k = a2.v WHERE (SELECT a0.k) IS NOT a2.k;
SELECT count(*), sum(a2.k) FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k LEFT JOIN f AS a2 ON a1.k = a2.v WHERE (SELECT a0.k) = a2.k;
SELECT count(*), sum(a2.k) FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k LEFT JOIN e AS a2 ON a1.k = a2.v WHERE (SELECT a0.k) = a2.k;
SELECT a0.k, a1.k, a2.k FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k LEFT JOIN e AS a2 ON a1.k = a2.v WHERE (SELECT count(*) FROM n) = a2.k;
SELECT a0.k, a1.k, a2.k FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k LEFT JOIN e AS a2 ON a1.k = a2.v WHERE a2.k IN (SELECT n.k FROM n WHERE n.v = a0.k);
SELECT a0.k, a1.k, a2.k FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k LEFT JOIN e AS a2 ON a1.k = a2.v WHERE a2.k NOT IN (SELECT n.k FROM n WHERE n.v = a0.k);
SELECT a0.k, a1.k, a2.k FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k LEFT JOIN f AS a2 ON a1.k = a2.v WHERE a2.k NOT IN (SELECT n.k FROM n WHERE n.v = a0.k);
SELECT a0.k, a1.k, a2.k FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k LEFT JOIN e AS a2 ON a1.k = a2.v WHERE a2.k IS NOT NULL OR EXISTS (SELECT 1 FROM n WHERE n.v = a0.k);
SELECT a0.k, a1.k, a2.k FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k LEFT JOIN f AS a2 ON a1.k = a2.v WHERE a2.k IS NOT NULL OR EXISTS (SELECT 1 FROM n WHERE n.v = a0.k);
SELECT a0.k, a1.k, a2.k FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k LEFT JOIN f AS a2 ON a1.k = a2.v WHERE a2.k IS NULL AND NOT EXISTS (SELECT 1 FROM n WHERE n.v = a0.k AND n.k = 1);
SELECT a0.k, a1.k FROM p AS a0 LEFT JOIN e AS a1 ON a0.k = a1.v WHERE (SELECT count(*) FROM n) = a1.k;
SELECT a0.k, a1.k FROM p AS a0 LEFT JOIN f AS a1 ON a0.k = a1.v WHERE (SELECT count(*) FROM n) > a1.k;
SELECT a0.k, a1.k FROM p AS a0 LEFT JOIN f AS a1 ON a0.k = a1.v WHERE a1.k NOT IN (SELECT n.k FROM n WHERE n.k IS NOT NULL);
SELECT a0.k, a1.k FROM p AS a0 LEFT JOIN f AS a1 ON a0.k = a1.v WHERE a1.k IN (SELECT n.k FROM n WHERE n.k IS NOT NULL) OR a1.k IS NULL;
SELECT a0.k, a1.k, a2.k FROM p AS a0 LEFT JOIN q AS a1 ON a0.k = a1.k LEFT JOIN f AS a2 ON a0.k = a2.v WHERE (SELECT count(*) FROM n) > a1.k + a2.k;
SELECT a0.k, a1.k, a2.k FROM p AS a0 LEFT JOIN q AS a1 ON a0.k = a1.k LEFT JOIN f AS a2 ON a1.k = a2.v WHERE a1.k + a2.k IS NULL;
SELECT a0.k, a1.k, a2.k FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k LEFT JOIN f AS a2 ON a1.k = a2.v WHERE a0.v + a2.k IS NULL;
SELECT a0.k, a1.k, a2.k FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k LEFT JOIN f AS a2 ON a1.k = a2.v WHERE a0.id + a2.k IS NULL;
SELECT a0.k, a1.k, a2.k FROM p AS a0 JOIN q AS a1 ON a0.k = a1.k LEFT JOIN f AS a2 ON a1.k = a2.v WHERE a0.rowid + a2.k > 1;
